SELECT CASE WHEN a.balance >= 64000 THEN 'high' WHEN a.balance >= 9000 THEN 'mid' ELSE 'low' END AS balance_bucket, COUNT(CASE WHEN t.txn_type = 'FEE' THEN 1 END) AS fee_count, ROUND(STDDEV(t.amount), 2) AS stddev_amount FROM transactions t RIGHT OUTER JOIN accounts a ON a.id = t.account_id LEFT OUTER JOIN customers c ON a.customer_id = c.id GROUP BY CASE WHEN a.balance >= 64000 THEN 'high' WHEN a.balance >= 9000 THEN 'mid' ELSE 'low' END
